-- ====================================================================
-- IEEE DigitalFest 2026 – Projects Expo: 156 Registered Participants & Certificates
-- Department of Information & Communication Engineering, IUB
-- ====================================================================

-- 1. Insert/Update Event Registered Count
UPDATE events 
SET seats_limit = 160, 
    registered_count = 156 
WHERE slug = '2026/digitalfest-projects-expo';

-- 2. Insert Registrations
ON CONFLICT (id) DO UPDATE SET status = 'ATTENDED';

-- 3. Insert Certificates
ON CONFLICT (code) DO NOTHING;
